H('407.d.2.A',4,"Comparing wetland construction progress to the schedule each week is part of which project phase?","monitoring and controlling",["initiating","closing","planning only"],"Monitoring tracks actual versus planned work.")
H('407.d.2.B',3,"On a water-treatment project, the person who coordinates schedule, budget, and team tasks is the:","project manager",["inspector","intern","customer"],"Managers coordinate the work.")
H('407.d.2.B',4,"On a design team, the member who writes meeting notes and tracks action items is the:","recorder",["auditor","sponsor","judge"],"Teams assign a recorder role.")
H('407.d.2.C',3,"A Gantt chart helps a project team see:","task start and end dates",["water quality only","employee ages","tax rates"],"Gantt charts show the schedule.")
H('407.d.2.C',4,"A task board with To Do, Doing, and Done columns is an example of a:","visual management tool",["water test","land survey","tax form"],"Boards show workflow status.")
H('407.d.2.D',3,"Putting current drawings in one shared folder with version numbers helps a team avoid:","using outdated plans",["saving money","hiring staff","meeting deadlines"],"Version control prevents errors.")
H('407.d.2.D',4,"A document log records who changed a specification and when. This supports:","tracking changes",["hiding mistakes","wasting time","avoiding review"],"Logs keep a history of changes.")
H('407.d.2.E',3,"A permit rule says effluent must stay under a set pollutant limit. For the design team, this is a:","requirement",["hobby","rumor","holiday"],"Permit limits are design requirements.")
H('407.d.2.E',4,"A final report, a working filter, and a maintenance guide due at project end are examples of:","deliverables",["constraints","risks","stakeholders"],"Deliverables are the products of a project.")
H('407.d.2.F',3,"A treatment project spends $40,000 on materials, $15,000 on equipment, and $25,000 on labor. The total cost is:","$80,000",["$65,000","$55,000","$95,000"],"40,000 + 15,000 + 25,000 = 80,000.")
H('407.d.2.F',4,"A project budget is $120,000 and $87,000 has been spent. How much remains?","$33,000",["$207,000","$43,000","$23,000"],"120,000 - 87,000 = 33,000.")
H('407.d.2.G',3,"Swapping a chlorine feed pump for a different model without review could cause new hazards. Management of change requires the swap to be:","reviewed and approved first",["made quietly","delayed forever","made by anyone"],"MOC reviews effects before changes.")
H('407.d.2.G',4,"A management of change review in a water plant mainly aims to keep a modification from creating:","unexpected safety or environmental risks",["bigger paychecks","extra holidays","new advertising"],"MOC protects people and the environment.")
H('407.d.3.A',3,"The Texas Engineering Practices Act regulates who may offer:","engineering services to the public",["restaurant meals","legal advice","medical care"],"The Act licenses engineering practice.")
H('407.d.3.A',4,"Under Texas law, a person who signs and seals engineering plans for the public must be a:","licensed professional engineer",["school volunteer","salesperson","apprentice only"],"Licensure protects the public.")
