H('407.d.9.N',4,"To test whether fertilizer amount affects algae growth, a student should keep all other factors:","the same",["different","unknown","random"],"Controlled variables keep tests fair.")
H('407.d.10.A',3,"Which energy source is renewable?","solar power",["coal","natural gas","oil"],"Sunlight is continually replenished.")
