H('407.d.11.D',4,"Healthy forests help natural resilience by reducing soil erosion and holding:","rainwater",["snacks","gold","screens"],"Forest soil absorbs rain.")
H('407.d.11.E',3,"The Air Quality Index (AQI) turns pollutant measurements into a:","single easy-to-read number",["song title","street address","tax code"],"AQI simplifies air data.")
H('407.d.11.E',4,"One city has an AQI of 40 and another has an AQI of 160. Which has worse air quality?","the city with 160",["the city with 40","both are equal","neither can be compared"],"Higher AQI means worse air.")
H('407.d.12.A',3,"A healthy ecosystem provides services such as clean water, pollination, and:","climate regulation",["traffic lights","television","printing"],"Ecosystems support human needs.")
H('407.d.12.A',4,"Biodiversity makes an ecosystem more stable because if one species declines, others can:","fill its role",["multiply forever","stop growing","leave the planet"],"Variety provides backups.")
H('407.d.12.B',3,"Farmland and timberland provide direct value by producing:","food and wood",["music","advertising","insurance"],"Direct production is a use value.")
H('407.d.12.B',4,"A forest that filters air and stores carbon provides an indirect value to people called an:","ecosystem service",["entertainment fee","parking permit","property tax"],"Indirect benefits are ecosystem services.")
H('407.d.12.C',3,"Restoring a damaged prairie by replanting native grasses is an example of land:","restoration",["extraction","subdivision","paving"],"Restoration repairs damaged land.")
H('407.d.12.C',4,"Leaving a wilderness area untouched so it stays as it is is called:","preservation",["restoration","development","mining"],"Preservation protects land from change.")
H('407.d.12.D',3,"Geographic information systems (GIS) and satellite images can be used to study how land cover changes:","over time",["by accident only","in music","in secret"],"Time series show land-use trends.")
H('407.d.12.D',4,"Comparing satellite images of a city taken 20 years apart can show how much farmland became:","urban development",["ocean","glaciers","space"],"Imagery shows land conversion.")
H('407.d.12.E',3,"A new highway can have a positive impact by easing traffic and a negative impact by:","fragmenting wildlife habitat",["adding wildlife habitat","cleaning rivers","lowering noise"],"Roads can split habitats.")
H('407.d.12.E',4,"When analyzing a development project, engineers report both positive and negative impacts in:","an environmental impact assessment",["a menu","a poem","a bill"],"Assessments document tradeoffs.")
H('407.d.12.F',3,"National parks and wildlife refuges are protected areas that help safeguard:","natural ecosystems",["parking lots","shopping malls","factories"],"Protected areas conserve nature.")
H('407.d.12.F',4,"A wildlife corridor between two protected areas helps animals to:","move safely between habitats",["avoid all food","stay in one cage","live without water"],"Corridors connect habitats.")
H('407.d.13.A',3,"Choosing a product with less packaging so that less trash is made is an example of waste:","reduction",["recycling","incineration","burial"],"Source reduction prevents waste.")
H('407.d.13.A',4,"Washing and refilling glass bottles instead of throwing them away is an example of:","reuse",["disposal","incineration","dumping"],"Reuse extends a product's life.")
H('407.d.13.B',3,"If every student in a school stops using single-use water bottles, the school saves:","plastic and energy",["sunlight","gravity","oxygen"],"Less production means fewer resources used.")
H('407.d.13.B',4,"Composting food scraps at home reduces the waste sent to landfills and returns nutrients to:","the soil",["the ocean floor","the atmosphere","the pipes"],"Compost enriches soil.")
H('407.d.13.C',3,"A modern landfill collects the liquid that drains through waste, called:","leachate",["effluent gas","compost tea","brine fuel"],"Leachate is treated to protect groundwater.")
H('407.d.13.C',4,"Landfill gas collection systems capture methane so it can be burned or used to make:","energy",["soil","paper","plastic"],"Methane is a fuel.")
H('407.d.13.D',3,"Which waste breaks down fastest in a compost pile?","banana peels",["glass bottles","aluminum cans","plastic bags"],"Organic waste decomposes quickly.")
H('407.d.13.D',4,"Plastic bags can last for hundreds of years in the environment because they are:","not easily broken down by microbes",["made of food","dissolved by rain","eaten by fish"],"Plastics resist decomposition.")
H('407.d.13.E',3,"Used batteries, paint, and pesticides are examples of waste that is:","hazardous",["edible","harmless","recyclable only"],"They contain toxic materials.")
H('407.d.13.E',4,"Hazardous waste should go to a special collection site rather than down a drain because it can:","contaminate soil and water",["improve plumbing","feed plants","clean pipes"],"Improper disposal spreads pollution.")
H('407.d.14.A',3,"The federal agency that writes and enforces rules such as clean air and clean water standards is the:","Environmental Protection Agency",["Federal Reserve","Postal Service","Weather Channel"],"The EPA regulates pollution.")
H('407.d.14.A',4,"The U.S. Fish and Wildlife Service is responsible for protecting:","endangered species and habitats",["highways","television signals","bank deposits"],"USFWS manages wildlife conservation.")
H('407.d.14.B',3,"In Texas, permits for wastewater discharges and air emissions are issued by the:","Texas Commission on Environmental Quality",["Texas Education Agency","Texas Workforce Commission","Texas Lottery Commission"],"The TCEQ issues environmental permits.")
H('407.d.14.B',4,"The Texas agency that manages state parks and fish and wildlife resources is the:","Texas Parks and Wildlife Department",["Texas Railroad Commission","Texas Department of Insurance","Texas Rangers"],"TPWD protects state natural resources.")
H('407.d.14.C',3,"Under the National Environmental Policy Act (NEPA), major federal projects must be reviewed through an:","environmental impact statement",["advertising plan","sports schedule","tax return"],"NEPA requires impact review.")
H('407.d.14.C',4,"NEPA requires federal agencies to consider environmental effects:","before making decisions",["after finishing projects","only if asked","never"],"Review comes before action.")
H('407.d.14.D',3,"In Texas, the Railroad Commission oversees the restoration of lands disturbed by:","surface coal mining",["school building","parades","farming only"],"The TRC regulates mine reclamation.")
H('407.d.14.D',4,"Reclamation of a mined site typically includes regrading the land and replanting:","vegetation",["parking meters","power lines","glass"],"Reclamation restores land cover.")
H('407.d.15.A',3,"Climate change is a persistent challenge partly because its causes and solutions involve:","many countries and industries",["one small town","no data","only chemistry"],"Global problems need broad cooperation.")
H('407.d.15.A',4,"Environmental problems like groundwater contamination can persist because pollutants may remain for:","decades",["seconds","minutes","hours"],"Some contaminants break down very slowly.")
H('407.d.15.B',3,"A student proposes rain barrels and permeable pavement to reduce a school's runoff. This is creating a:","solution to a current challenge",["new law of physics","school holiday","lunch menu"],"Engineers design solutions for society.")
H('407.d.15.B',4,"A good solution to a community problem must meet people's needs and also:","limit harm to the environment",["ignore costs","avoid testing","hide data"],"Sustainable solutions balance needs.")
H('407.d.15.C',3,"A resilient solution should be able to withstand a disruption and then:","recover quickly",["collapse","disappear","double in cost"],"Resilience means bouncing back.")
H('407.d.15.C',4,"Building redundancy into a system, such as a second pump, supports resilience by:","providing a backup if one part fails",["doubling the noise","avoiding all maintenance","removing safeguards"],"Backups keep systems running.")
H('407.d.15.D',3,"The energy used to mine materials, make a product, ship it, and dispose of it is part of its:","life cycle energy cost",["sales tax","brand value","shelf color"],"Life cycle analysis totals energy use.")
H('407.d.15.D',4,"Describing a product's life cycle starts with extraction of raw materials and ends with:","disposal or recycling",["design","marketing","naming"],"The life cycle ends at end of life.")
H('408.d.1',3,"A pump engineer discovers a design flaw that could cause a hydraulic line to burst near workers. Ethics requires the engineer to:","report the flaw and act to fix it",["keep it secret","wait for an injury","blame the operator"],"Safety duties come first.")
H('408.d.1',4,"An engineer's professional code says the safety of the public must be held:","paramount",["optional","secondary","irrelevant"],"Public safety outranks other concerns.")
H('408.d.2.A',3,"A student sees that water drains faster from a tall tank than a short one and asks why. This question comes from:","an observation",["a rumor","a law","a budget"],"Questions start with observations.")
H('408.d.2.A',4,"Defining the problem 'reduce pump energy use by 15 percent' gives the team a:","measurable goal",["guess","slogan","hobby"],"Goals with numbers can be tested.")
H('408.d.2.B',3,"Measuring how fast three different oils flow down a ramp is a comparative investigation because it:","compares results among samples",["avoids measuring","uses no oil","has no result"],"Comparative studies contrast samples.")
H('408.d.2.B',4,"In an experiment on flow rate, the variable the investigator measures as the result is the:","dependent variable",["independent variable","constant","control rod"],"The dependent variable is the outcome.")
H('408.d.2.C',3,"When working with a pressurized hydraulic test rig, a student should wear:","safety glasses",["sandals","a scarf","headphones only"],"Eye protection guards against spray.")
H('408.d.2.C',4,"A student notices fluid leaking from a lab pump. The correct first step is to:","stop the pump and tell the instructor",["touch the leak","keep working","step over the puddle"],"Stop the hazard and report it.")
H('408.d.2.D',3,"To measure the inside diameter of a small pipe fitting precisely, a student could use:","dial calipers",["a bathroom scale","a thermometer","a stopwatch"],"Calipers measure small dimensions.")
H('408.d.2.D',4,"A graduated cylinder is the right tool for measuring the:","volume of a liquid",["length of a pipe","angle of a bend","speed of a car"],"Graduated cylinders measure liquid volume.")
H('408.d.2.E',3,"A student records 750 milliliters of water. In liters, this is:","0.75 liters",["7.5 liters","75 liters","0.075 liters"],"750 / 1,000 = 0.75.")
H('408.d.2.E',4,"A pipe is 36 inches long. In feet, its length is:","3 feet",["12 feet","30 feet","0.3 feet"],"36 / 12 = 3.")
H('408.d.2.F',3,"A student records the number of seconds a funnel takes to drain each trial in a spreadsheet. These are:","quantitative data",["qualitative data","opinions","theories"],"Measured numbers are quantitative.")
H('408.d.2.F',4,"Notes such as 'the oil looked cloudy and thick' are:","qualitative observations",["numerical measurements","calculated results","unit conversions"],"Descriptions are qualitative.")
H('408.d.2.G',3,"A drawing of a water tower with arrows showing the flow of water is a:","model of a system",["law","hypothesis","unit"],"Diagrams model how systems work.")
H('408.d.2.G',4,"A computer simulation of water flowing through a pipe network is a model that helps predict:","flow behavior",["weather","grades","prices"],"Simulations predict system behavior.")
H('408.d.2.H',3,"A statement predicting that thicker oil will flow more slowly, which can be tested, is a:","hypothesis",["law","unit","summary"],"A hypothesis is a testable prediction.")
H('408.d.2.H',4,"A scientific law, such as conservation of mass, differs from a hypothesis because a law has been:","supported by extensive evidence",["guessed once","never tested","voted on"],"Laws rest on repeated confirmation.")
H('408.d.3.A',3,"A small scale model of a spillway is cheaper to test, but its flow may not match the real spillway's because of:","scale effects",["paint effects","price effects","name effects"],"Scaling can change fluid behavior.")
H('408.d.3.A',4,"A model that simplifies a pipe network by ignoring friction will likely:","overestimate the flow",["underestimate the flow","be exact","stop working"],"Friction slows real flow.")
H('408.d.3.B',3,"A graph of flow rate against pipe diameter slopes upward. This pattern shows that larger pipes carry:","more flow",["less flow","no flow","colder flow"],"Flow increases with diameter.")
H('408.d.3.B',4,"To judge how consistent repeated flow measurements are, an analyst can calculate their:","standard deviation",["color","weight","shape"],"Standard deviation measures spread.")
H('408.d.3.C',3,"A pump delivers 90 gallons in 6 minutes. Its flow rate is:","15 gallons per minute",["96 gallons per minute","540 gallons per minute","0.07 gallons per minute"],"90 / 6 = 15.")
H('408.d.3.C',4,"If the flow rate is multiplied by 2 while the pipe area stays the same, the fluid velocity:","doubles",["halves","stays the same","triples"],"Velocity = flow rate / area.")
H('408.d.3.D',3,"After a test shows a new nozzle design sprays unevenly, the team evaluates the design by comparing results with its:","performance criteria",["paint colors","trophy list","lunch plans"],"Evaluation compares data to criteria.")
H('408.d.3.D',4,"An experiment that changes two variables at once makes causes hard to separate, so a test should change:","one variable at a time",["every variable","no variables","variables at random"],"Controlled tests isolate effects.")
H('408.d.4.A',3,"A student claims a wider drain empties a tank faster and supports it with timed trials. The claim is stronger because it is backed by:","measured data",["opinion","popularity","luck"],"Evidence strengthens claims.")
H('408.d.4.A',4,"A proposed solution to a clogged pipe should be supported by data and a model showing that it will:","restore the intended flow",["add more clogs","hide the pipe","slow every pump"],"Solutions must meet the goal.")
H('408.d.4.B',3,"A team explains its pump design with a diagram, a data table, and a short talk. They are communicating:","in several ways",["in secret","with no evidence","only by guessing"],"Multiple formats help audiences.")
H('408.d.4.B',4,"When a team presents its results, listeners can best follow if the explanation uses clear labels and:","correct units",["slang","jokes","silence"],"Units make numbers meaningful.")
H('408.d.4.C',3,"A respectful way to challenge a classmate's flow calculation is to:","point to the step you think is wrong and show why",["call them careless","ignore the work","interrupt loudly"],"Argue the ideas, not the person.")
H('408.d.4.C',4,"A strong scientific argument about a fluid test includes a claim, evidence, and:","reasoning",["a joke","an insult","a prize"],"Reasoning links evidence to the claim.")
H('408.d.5.A',3,"To critique a report claiming a new coating reduces drag, a reader checks whether the report includes:","data from controlled tests",["a famous author","bright colors","a long title"],"Evaluate the evidence.")
H('408.d.5.A',4,"A claim based on a single trial of a wind-tunnel test is weak because the result might be:","a random fluke",["always exact","impossible","a law"],"Repeated trials build confidence.")
H('408.d.5.B',3,"Bernoulli's work in the 1700s on fluid motion has influenced modern:","airplane wing design",["bakery recipes","poetry","sports rules"],"His principle relates speed and pressure in fluids.")
H('408.d.5.B',4,"Research on streamlined shapes has changed engineering by helping vehicles use less:","fuel",["time zones","space only","steel only"],"Reduced drag saves energy.")
H('408.d.5.C',3,"A student interested in fluid engineering careers could learn more from a professional group such as the:","American Society of Mechanical Engineers",["Society of Pastry Chefs","National Football League","Bureau of Fashion"],"Professional societies share career information.")
H('408.d.5.C',4,"Visiting a water treatment plant or hydropower station lets students observe:","fluid systems in real use",["only paperwork","no equipment","unrelated jobs"],"Field visits show applications.")
H('408.d.6.A',3,"Large volumes of liquid fuel are efficiently moved across the country by:","pipelines",["backpacks","bicycles","kites"],"Pipelines transport fluids efficiently.")
H('408.d.6.A',4,"Storing fluids in tanks with a rounded or cylindrical shape helps them to:","withstand pressure evenly",["fall over easily","hold no fluid","float away"],"Curved walls distribute stress.")
H('408.d.6.B',3,"In a hydroelectric dam, moving water turns a:","turbine",["candle","mirror","balloon"],"The turbine drives a generator.")
H('408.d.6.B',4,"In a hydraulic system, a fluid transmits power by carrying:","pressure",["sound only","color","magnets"],"Pressure transmits force through fluids.")
H('408.d.6.C',3,"The force that opposes an airplane's motion through the air is:","drag",["lift","weight","thrust"],"Drag acts against motion.")
H('408.d.6.C',4,"The upward force on a wing that helps an airplane stay in the air is:","lift",["drag","gravity","friction only"],"Lift counters weight.")
H('408.d.7.A',3,"A fluid differs from a solid because it takes the shape of its:","container",["magnet","label","scale"],"Fluids flow to fill their container.")
H('408.d.7.A',4,"Which of these is a fluid?","motor oil",["steel beam","granite block","wooden plank"],"Liquids and gases are fluids.")
H('408.d.7.B',3,"A fluid whose viscosity stays constant at a given temperature regardless of shear rate is called:","Newtonian",["magnetic","crystalline","brittle"],"Water and air behave as Newtonian fluids.")
H('408.d.7.B',4,"Ketchup, which gets thinner when shaken, is an example of a fluid that is:","non-Newtonian",["Newtonian","solid","gaseous"],"Its viscosity changes with shear.")
H('408.d.7.C',3,"Which fluid is usually treated as incompressible?","liquid water",["air","helium","steam"],"Liquids change volume very little under pressure.")
H('408.d.7.C',4,"Gases are generally considered compressible because their:","density changes noticeably with pressure",["color changes","names change","mass disappears"],"Gas volume shrinks under pressure.")
H('408.d.7.D',3,"Density is defined as mass per unit:","volume",["time","length","charge"],"Density = mass / volume.")
H('408.d.7.D',4,"Specific gravity compares a liquid's density to the density of:","water",["air","steel","sand"],"Water is the reference for liquids.")
H('408.d.7.E',3,"A student measures a liquid with mass 500 g in 400 mL. The density is:","1.25 g/mL",["0.8 g/mL","200 g/mL","100 g/mL"],"500 / 400 = 1.25.")
H('408.d.7.E',4,"A hydrometer floats in a liquid to directly measure the liquid's:","specific gravity",["temperature","length","pressure"],"Hydrometers read specific gravity.")
H('408.d.7.F',3,"A fluid has density 800 kg/m3. Its specific gravity relative to water (1,000 kg/m3) is:","0.8",["8","1.25","800"],"800 / 1,000 = 0.8.")
H('408.d.7.F',4,"Specific weight equals density times g. For water at 1,000 kg/m3 and g = 9.8 m/s2, the specific weight is about:","9,800 N/m3",["980 N/m3","98 N/m3","98,000 N/m3"],"1,000 x 9.8 = 9,800.")
H('408.d.7.G',3,"Following a single parcel of fluid as it moves through a pipe uses which viewpoint?","Lagrangian (material) frame",["Eulerian (fixed) frame","Newtonian frame","random frame"],"Lagrangian frames move with the material.")
H('408.d.7.G',4,"Watching how fluid velocity changes at a fixed point in a pipe uses which viewpoint?","Eulerian (spatial) frame",["Lagrangian (material) frame","Galilean frame","static frame"],"Eulerian frames stay fixed in space.")
H('408.d.7.H',3,"In the ideal gas law PV = nRT, the variable T stands for:","absolute temperature",["time","thickness","torque"],"T must be in kelvin.")
H('408.d.7.H',4,"If the temperature of a gas in a rigid container rises, its pressure:","increases",["decreases","stays zero","disappears"],"Pressure is proportional to temperature at fixed volume.")
H('408.d.7.I',3,"In steady flow, the law of conservation of mass says the mass flow rate into a pipe equals the mass flow rate:","leaving it",["created inside it","destroyed inside it","doubled inside it"],"Mass in equals mass out at steady state.")
H('408.d.7.I',4,"The law of conservation of energy says that energy in a fluid system can change form but cannot be:","created or destroyed",["measured","transferred","converted"],"Total energy is conserved.")
H('408.d.7.J',3,"The no-slip condition says that fluid touching a solid wall has the same velocity as:","the wall",["the center of the pipe","the sound","the ambient air only"],"Fluid sticks to the surface.")
H('408.d.7.J',4,"Because of the no-slip condition, fluid velocity in a pipe is lowest:","at the pipe wall",["at the center","everywhere equally","at the inlet only"],"Velocity is zero at a stationary wall.")
H('408.d.8.A',3,"A force of 200 N acts on an area of 0.5 m2. The pressure is:","400 Pa",["100 Pa","200 Pa","0.0025 Pa"],"P = F/A = 200/0.5 = 400.")
H('408.d.8.A',4,"If the same force is applied over a smaller area, the pressure:","increases",["decreases","stays the same","becomes zero"],"Pressure is inversely proportional to area.")
H('408.d.8.B',3,"In a hydraulic jack, a small piston of area 2 cm2 is pushed with 50 N. The large piston has area 20 cm2. The output force is:","500 N",["5 N","50 N","5,000 N"],"Force scales with the area ratio of 10.")
H('408.d.8.B',4,"In a hydraulic system, pressure applied to a confined fluid is transmitted:","equally in all directions",["only upward","only to the largest piston","not at all"],"This is Pascal's law.")
H('408.d.8.C',3,"Absolute pressure equals gauge pressure plus:","atmospheric pressure",["vapor pressure only","zero","specific gravity"],"Gauge pressure is measured relative to the atmosphere.")
H('408.d.8.C',4,"A tire gauge reads 32 psi. If atmospheric pressure is about 14.7 psi, the absolute pressure is about:","46.7 psi",["17.3 psi","32 psi","470 psi"],"32 + 14.7 = 46.7.")
H('408.d.8.D',3,"A Bourdon tube pressure gauge works because a curved tube tends to:","straighten when pressurized",["melt","freeze","change color"],"The tube's motion moves the needle.")
H('408.d.8.D',4,"A manometer measures pressure by comparing the heights of:","a liquid column",["two wires","two clocks","a battery"],"Height difference reflects pressure.")
H('408.d.8.E',3,"According to Archimedes' principle, the buoyant force on an object equals the weight of the:","fluid displaced",["object itself","container","air above"],"Buoyancy equals displaced fluid weight.")
H('408.d.8.E',4,"A block displaces 3 liters of water (about 3 kg). The buoyant force is about:","29.4 N",["3 N","9.8 N","300 N"],"3 x 9.8 = 29.4.")
H('408.d.8.F',3,"Hydrostatic pressure in a still fluid increases with:","depth",["width","color","speed"],"Deeper fluid supports more weight above.")
H('408.d.8.F',4,"Using P = rho x g x h, the pressure from a 10 m column of water (rho = 1,000 kg/m3, g = 9.8 m/s2) is:","98,000 Pa",["9,800 Pa","980 Pa","980,000 Pa"],"1,000 x 9.8 x 10 = 98,000.")
H('408.d.9.A',3,"Fluid flow whose velocity profile no longer changes along the pipe is called:","fully developed",["just started","chaotic only","stationary"],"Developed flow has a constant profile.")
H('408.d.9.A',4,"Steady-state flow means that at any point, fluid properties do not change with:","time",["position","pipe size","fluid type"],"Steady means time-independent.")
H('408.d.9.B',3,"In laminar flow in a round pipe, the velocity profile is:","parabolic",["flat","square","spiky"],"Velocity is highest at the center.")
H('408.d.9.B',4,"An idealized uniform velocity profile assumes all fluid across the pipe moves at:","the same speed",["different speeds","zero speed","random speeds"],"Uniform means equal velocity.")
H('408.d.9.C',3,"A line that shows the path a single fluid particle follows over time is a:","pathline",["contour","timeline","baseline"],"Pathlines trace particle motion.")
H('408.d.9.C',4,"Injecting dye continuously from one point in a flow produces a:","streakline",["gridline","skyline","shoreline"],"Streaklines mark all particles from one point.")
H('408.d.9.D',3,"Water flows at 2 m/s through a pipe with a cross-sectional area of 0.05 m2. The volumetric flow rate is:","0.1 m3/s",["0.025 m3/s","40 m3/s","2.05 m3/s"],"Q = vA = 2 x 0.05 = 0.1.")
H('408.d.9.D',4,"By the continuity equation, when a pipe narrows, the fluid speed in the narrow section:","increases",["decreases","stays the same","reverses"],"Smaller area means higher speed.")
H('408.d.9.E',3,"Bernoulli's equation relates pressure, velocity, and:","elevation",["color","pipe age","label"],"It balances pressure, kinetic, and potential energy.")
H('408.d.9.E',4,"For a horizontal pipe with steady flow, where fluid speed is higher, the pressure is:","lower",["higher","unchanged","infinite"],"Faster flow has lower pressure.")
H('408.d.9.F',3,"Fluid enters a pipe at 1 m/s through area A and then flows through a section of area A/2. The speed there is:","2 m/s",["0.5 m/s","1.5 m/s","4 m/s"],"Halving the area doubles the speed.")
H('408.d.9.F',4,"A pipe's diameter is halved. The cross-sectional area becomes:","one-fourth",["one-half","double","unchanged"],"Area depends on the square of diameter.")
H('408.d.9.G',3,"Torricelli's equation gives the exit speed v = sqrt(2gh) from a hole in a tank. If the water level h is raised, the exit speed:","increases",["decreases","stays the same","reverses"],"Higher head gives faster outflow.")
H('408.d.9.G',4,"Using v = sqrt(2gh) with g = 10 m/s2 and h = 20 m, the exit speed is:","20 m/s",["10 m/s","40 m/s","200 m/s"],"sqrt(2 x 10 x 20) = sqrt(400) = 20.")
H('408.d.9.H',3,"The Reynolds number compares inertial forces to:","viscous forces",["magnetic forces","gravity only","sound forces"],"Re = inertia / viscosity.")
H('408.d.9.H',4,"A flow with a low Reynolds number is most likely:","laminar",["turbulent","supersonic","frozen"],"Low Re means smooth flow.")
H('408.d.9.I',3,"A free jet of water leaves a nozzle and strikes a flat plate. The force on the plate depends on the jet's mass flow rate and its:","velocity",["color","label","temperature"],"Force relates to momentum change.")
H('408.d.9.I',4,"By Newton's laws, the force a fluid jet exerts on a plate equals the rate of change of the jet's:","momentum",["color","volume only","temperature"],"Force = rate of change of momentum.")
H('408.d.10.A',3,"Smooth flow in which fluid moves in parallel layers is called:","laminar flow",["turbulent flow","static flow","compressed flow"],"Laminar flow is orderly.")
H('408.d.10.A',4,"Flow with eddies and chaotic mixing is called:","turbulent flow",["laminar flow","still flow","sonic flow"],"Turbulent flow is irregular.")
H('408.d.10.B',3,"For flow in a pipe, a Reynolds number above about 4,000 generally indicates:","turbulent flow",["laminar flow","no flow","frozen flow"],"High Re means turbulence.")
H('408.d.10.B',4,"Water (density 1,000 kg/m3, viscosity 0.001 Pa s) moves at 0.1 m/s in a 0.02 m pipe. Re = (rho v D)/mu equals:","2,000",["200","20,000","0.002"],"1,000 x 0.1 x 0.02 / 0.001 = 2,000.")
H('408.d.10.C',3,"Lift is the force on a body in a fluid that acts:","perpendicular to the flow",["parallel to the flow","toward the sun","in all directions equally"],"Lift is perpendicular to the oncoming flow.")
H('408.d.10.C',4,"Drag is the force on a body in a fluid that acts:","in the direction opposite its motion",["upward only","toward the center","without direction"],"Drag opposes motion.")
H('408.d.10.D',3,"Viscosity is a fluid's resistance to:","flow or shearing",["freezing","compression only","being weighed"],"Viscosity measures internal friction.")
H('408.d.10.D',4,"Honey is more viscous than water, so for the same shear rate it requires:","greater shear force",["less shear force","no shear force","negative force"],"Shear stress = viscosity x shear rate.")
H('408.d.10.E',3,"The drag force on a body depends on fluid density, the body's frontal area, its drag coefficient, and the square of its:","speed",["color","name tag","label"],"Drag grows with the square of velocity.")
H('408.d.10.E',4,"If a vehicle's speed doubles, the drag force becomes about:","four times as large",["twice as large","the same","half as large"],"Drag varies with speed squared.")
H('408.d.10.F',3,"A wind-tunnel test to measure the drag coefficient of a model car would record drag force, air speed, and:","the frontal area",["the car's price","the tunnel's color","the day of the week"],"Cd = 2F / (rho v^2 A).")
H('408.d.10.F',4,"To compare the drag coefficients of a sphere and a streamlined shape fairly, the tests should use the same:","fluid and air speed",["color","names","paint"],"Controlled conditions give fair comparisons.")
H('408.d.11.A',3,"Flow at low speed, such as water in a pipe, is usually modeled as incompressible because its density:","stays nearly constant",["varies wildly","doubles","disappears"],"Density barely changes at low speeds.")
